function routeLocale(locale) {
  var value = String(locale || "").replace(/_/g, "-")
  var lower = value.toLowerCase()
  var subtags = lower.split("-")
  var language = subtags[0]
  var script = ""
  var region = ""
  for (var i = 1; i < subtags.length; i++) {
    if (!script && /^[a-z]{4}$/.test(subtags[i])) script = subtags[i]
    else if (!region && (/^[a-z]{2}$/.test(subtags[i]) || /^\d{3}$/.test(subtags[i]))) region = subtags[i]
  }
  if (language === "pt") {
    if (subtags.length === 1 || region === "br") return "pt_BR"
    return "en"
  }
  if (language === "zh") {
    if (subtags.length === 1) return "zh_CN"
    if (script === "hant" || region === "tw" || region === "hk" || region === "mo") return "en"
    if (script === "hans" || region === "cn" || region === "sg") return "zh_CN"
    return "en"
  }
  return catalogs[language] ? language : null
}

function normalizeLocale(locale) {
  return routeLocale(locale) || "en"
}

function resolveLocale(uiLanguages, localeName) {
  var candidates = []
  if (uiLanguages && typeof uiLanguages === "object" && typeof uiLanguages.length === "number" && isFinite(uiLanguages.length) && uiLanguages.length >= 0) {
    var length = Math.floor(uiLanguages.length)
    for (var i = 0; i < length; i++) candidates.push(uiLanguages[i])
  }
  if (localeName) candidates.push(localeName)
  for (var j = 0; j < candidates.length; j++) {
    var resolved = routeLocale(candidates[j])
    if (resolved) return resolved
  }
  return "en"
}

function currentLocale() {
  var locale = Qt.locale()
  return resolveLocale(locale.uiLanguages || [], locale.name || "")
}

function t(locale, key, params) {
  var selected = catalogs[normalizeLocale(locale)] || en
  var message = selected[key] !== undefined ? selected[key] : (en[key] !== undefined ? en[key] : key)
  return String(message).replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, function(match, name) {
    return params && params[name] !== undefined ? String(params[name]) : match
  })
}
